(() => {
  'use strict';

  const INSTANCE_KEY = '__daoyuanCultivationReaderV2';
  const STYLE_ID = 'daoyuan-cultivation-reader-style-v2';
  const PAPER_SELECTOR = '[data-daoyuan-reader=\"v2\"]';
  const TERM_WIDGET_URL = 'https://cdn.daoyuan.mayuworld.com/scripts/prod/latest/daoyuan-term-widget.min.js';
  const TERM_WIDGET_SCRIPT_ID = 'daoyuan-reader-term-widget-loader';
  const TERM_WIDGET_PREF = 'daoyuan-reader-terms-enabled';
  let termWidgetLoading = null;
  let termWidgetManaged = false;
  let termWidgetInstance = null;

  const CSS = `
    :root { color-scheme: dark; }
    .dy-reader-v2 {
      --dy-ink: #0d1014;
      --dy-paper: #19191a;
      --dy-paper-2: #202328;
      --dy-gold: #d8c188;
      --dy-gold-dim: #806f45;
      --dy-cinnabar: #a94f45;
      --dy-text: #e3dfcf;
      --dy-text-soft: #b9b39f;
      position: relative;
      isolation: isolate;
      display: block;
      width: 100%;
      max-width: none;
      margin: 0.7rem 0;
      overflow: hidden;
      box-sizing: border-box;
      color: var(--dy-text);
      color-scheme: dark;
      border: 1px solid rgba(216, 193, 136, 0.22);
      border-left: 3px solid rgba(216, 193, 136, 0.66);
      border-radius: 4px;
      background:
        radial-gradient(circle at 14% -8%, rgba(216,193,136,.09), transparent 30%),
        radial-gradient(circle at 92% 8%, rgba(125,89,65,.10), transparent 24%),
        repeating-linear-gradient(0deg, rgba(255,255,255,.012) 0 1px, transparent 1px 4px),
        linear-gradient(145deg, rgba(30,29,28,.98), rgba(19,23,29,.99) 58%, rgba(12,15,19,.99));
      box-shadow: 0 12px 32px rgba(0,0,0,.32), inset 0 0 70px rgba(216,193,136,.025);
      font-family: 'DaoYuan Serif','Noto Serif SC','Songti SC','STSongti SC','SimSun',serif;
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }
    .dy-reader-v2::before {
      content: '';
      position: absolute;
      inset: 0;
      z-index: -1;
      pointer-events: none;
      background:
        linear-gradient(90deg, rgba(216,193,136,.055), transparent 8%, transparent 92%, rgba(216,193,136,.035)),
        radial-gradient(ellipse at center, transparent 48%, rgba(0,0,0,.22) 100%);
    }
    .mes_text .dy-reader-v2 .dy-reader-v2__header {
      position: relative;
      display: grid;
      justify-items: center;
      gap: .25rem;
      padding: 1.35rem 1.4rem 1.05rem;
      text-align: center;
      border-bottom: 1px solid rgba(216,193,136,.16);
      background: linear-gradient(180deg, rgba(216,193,136,.055), transparent);
    }
    .dy-reader-v2__settings-button {
      position: absolute; right: clamp(3.2rem, 6vw, 4.4rem); top: .95rem;
      display: grid; place-items: center; width: 2rem; height: 2rem; padding: 0;
      color: #b9a875; background: rgba(12,15,19,.72);
      border: 1px solid rgba(216,193,136,.3); border-radius: 50%;
      z-index: 21; touch-action: manipulation;
      font: 600 .9rem/1 system-ui, sans-serif; cursor: pointer;
    }
    .dy-reader-v2__settings-button:hover { color: #ead9bc; border-color: rgba(216,193,136,.65); }
    .dy-reader-v2__settings-button:focus-visible { outline: 2px solid #d8c188; outline-offset: 2px; }
    .dy-reader-v2__settings-button:disabled { opacity: .42; cursor: not-allowed; }
    .mes_text .dy-reader-v2 .dy-reader-v2__settings {
      position: absolute; z-index: 20; right: 1rem; top: 3.35rem;
      display: grid; gap: .55rem; min-width: 12rem; padding: .8rem;
      color: #d8d1bb; background: rgba(12,15,19,.97);
      border: 1px solid rgba(216,193,136,.32); border-radius: .35rem;
      box-shadow: 0 .8rem 2rem rgba(0,0,0,.45); text-align: left;
      font: .8rem/1.4 system-ui, sans-serif;
    }
    .mes_text .dy-reader-v2 .dy-reader-v2__settings[hidden] { display: none; }
    .dy-reader-v2__settings label { display: grid; gap: .38rem; margin: 0; }
    .dy-reader-v2__settings select {
      width: 100%; min-height: 2.25rem; padding: .38rem .65rem;
      color: #e3dfcf; background: #181c22;
      border: 1px solid rgba(216,193,136,.34); border-radius: .25rem;
      font: inherit; color-scheme: dark;
    }
    .dy-reader-v2__settings select:hover { border-color: rgba(216,193,136,.58); }
    .dy-reader-v2__settings select:focus { outline: 2px solid #d8c188; outline-offset: 1px; }
    .dy-reader-v2__settings select:disabled { color: #77736a; background: #111318; border-color: #333; }
    .dy-reader-v2__settings option { color: #e3dfcf; background: #181c22; }
    .dy-reader-v2__settings input[type="range"] {
      width: 100%; min-height: 1.5rem; margin: 0; accent-color: #d8c188;
      color-scheme: dark; cursor: pointer;
    }
    .dy-reader-v2__settings input[type="range"]:focus-visible { outline: 2px solid #d8c188; outline-offset: 2px; }
    .dy-reader-v2__settings input[type="range"]:disabled { opacity: .42; cursor: not-allowed; }
    .dy-reader-v2__size-row { display: flex; justify-content: space-between; gap: .8rem; color: #d8d1bb; }
    .dy-reader-v2__size-value { color: #b9a875; font-variant-numeric: tabular-nums; }
    .dy-reader-v2[data-font="song"] { font-family: 'Noto Serif SC','Songti SC','STSongti SC','SimSun',serif; }
    .dy-reader-v2[data-font="fangsong"] { font-family: 'FangSong','STFangsong','仿宋',serif; }
    .dy-reader-v2[data-font="kai"] { font-family: 'Kaiti SC','STKaiti','KaiTi','楷体',serif; }
    .dy-reader-v2[data-font="hei"] { font-family: 'PingFang SC','Microsoft YaHei','Noto Sans CJK SC',sans-serif; }
    .mes_text .dy-reader-v2 .dy-reader-v2__dialogue {
      display: grid; grid-template-columns: 3.6rem minmax(0,1fr); gap: .8rem;
      align-items: start; margin: 1.35em 0; padding: .75em .9em;
      color: #ead9bc; background: rgba(216,193,136,.045);
      border: 1px solid rgba(216,193,136,.12); border-inline-start: 2px solid rgba(216,193,136,.42);
      border-radius: .3rem; text-indent: 0; text-align: left;
    }
    .dy-reader-v2__portrait {
      width: 3.6rem; height: 3.6rem; border-radius: 50%; object-fit: cover; object-position: top center;
      border: 1px solid rgba(216,193,136,.48); background: #22262b;
      box-shadow: 0 0 0 2px rgba(0,0,0,.25);
    }
    .dy-reader-v2__portrait-fallback {
      display: grid; place-items: center; color: #c97869; font-size: .85rem;
    }
    .dy-reader-v2__speech { display: grid; gap: .2rem; align-self: center; line-height: 1.72; }
    .dy-reader-v2__speaker { color: #9d8b5c; font: 600 .72em/1.2 system-ui, sans-serif; letter-spacing: .08em; }
    .dy-reader-v2__spoken-text { color: #ead9bc; font-style: italic; font-family: inherit; }
    .dy-reader-v2__dialogue + .dy-reader-v2__dialogue { margin-top: -.55em; }
        .dy-reader-v2__size-scale {
      display: grid !important; grid-template-columns: 1rem minmax(7rem,1fr) 1.4rem !important;
      align-items: center !important; gap: .55rem !important; margin-top: .15rem !important;
    }
    .dy-reader-v2__size-glyph { color: #918d82; font: 600 .78rem/1 system-ui,sans-serif; text-align: center; }
    .dy-reader-v2__size-glyph--large { font-size: 1.45rem; font-weight: 500; }
    .dy-reader-v2__settings .dy-reader-v2__size-scale input[type="range"] {
      appearance: none !important; -webkit-appearance: none !important;
      display: block !important; width: 100% !important; height: 1.5rem !important; min-height: 1.5rem !important;
      margin: 0 !important; padding: 0 !important; border: 0 !important; border-radius: 0 !important;
      background: transparent !important; box-shadow: none !important; cursor: pointer;
    }
    .dy-reader-v2__settings .dy-reader-v2__size-scale input[type="range"]::-webkit-slider-runnable-track {
      height: .28rem !important; border: 0 !important; border-radius: 999px !important;
      background: linear-gradient(to right,#0a84ff 0 var(--dy-size-progress,33.33%),#555960 var(--dy-size-progress,33.33%) 100%) !important;
    }
    .dy-reader-v2__settings .dy-reader-v2__size-scale input[type="range"]::-webkit-slider-thumb {
      appearance: none !important; -webkit-appearance: none !important;
      width: 1.28rem !important; height: 1.28rem !important; margin-top: -.5rem !important;
      border: 0 !important; border-radius: 50% !important; background: #f7f7f8 !important;
      box-shadow: 0 1px 5px rgba(0,0,0,.55) !important;
    }
    .dy-reader-v2__settings .dy-reader-v2__size-scale input[type="range"]::-moz-range-track {
      height: .28rem !important; border: 0 !important; border-radius: 999px !important; background: #555960 !important;
    }
    .dy-reader-v2__settings .dy-reader-v2__size-scale input[type="range"]::-moz-range-progress {
      height: .28rem !important; border-radius: 999px !important; background: #0a84ff !important;
    }
    .dy-reader-v2__settings .dy-reader-v2__size-scale input[type="range"]::-moz-range-thumb {
      width: 1.28rem !important; height: 1.28rem !important; border: 0 !important;
      border-radius: 50% !important; background: #f7f7f8 !important; box-shadow: 0 1px 5px rgba(0,0,0,.55) !important;
    }
    .dy-reader-v2__terms-toggle {
      display: grid !important; grid-template-columns: 2.25rem minmax(0,1fr) !important;
      align-items: center !important; column-gap: .62rem !important;
      width: 100% !important; min-height: 2.15rem !important; margin: .15rem 0 0 !important; padding: .18rem 0 !important;
      color: #d8d1bb !important; background: transparent !important; border: 0 !important;
      border-radius: .25rem !important; box-shadow: none !important; font: inherit !important; line-height: 1.4 !important;
      text-align: left !important; cursor: pointer;
    }
    .dy-reader-v2__terms-track {
      display: block !important; position: relative !important;
      width: 2.25rem !important; height: 1.18rem !important; min-width: 2.25rem !important; min-height: 1.18rem !important;
      margin: 0 !important; padding: 0 !important; box-sizing: border-box !important;
      border: 1px solid #514c3d !important; border-radius: 999px !important;
      background: #393b40 !important; transform: none !important; transition: background .16s,border-color .16s;
    }
    .dy-reader-v2__terms-track::after {
      content: ''; display: block !important; position: absolute !important;
      width: .76rem !important; height: .76rem !important; left: .16rem !important; top: .14rem !important;
      margin: 0 !important; padding: 0 !important; border: 0 !important;
      border-radius: 50% !important; background: #fff !important; box-shadow: 0 1px 4px rgba(0,0,0,.55) !important;
      transition: transform .16s,background .16s;
    }
    .dy-reader-v2__terms-text { display: block !important; min-width: 0; margin: 0 !important; padding: 0 !important; }
    .dy-reader-v2__terms-toggle[aria-checked="true"] .dy-reader-v2__terms-track {
      background: #0a84ff !important; border-color: #0a84ff !important;
    }
    .dy-reader-v2__terms-toggle[aria-checked="true"] .dy-reader-v2__terms-track::after {
      transform: translateX(1.08rem); background: #fff;
    }
    .dy-reader-v2__terms-toggle:focus-visible { outline: 2px solid #d8c188 !important; outline-offset: 2px; }
    .dy-reader-v2__terms-toggle[aria-disabled="true"] { opacity: .42; cursor: wait; color: #77736a !important; }
    .dy-reader-v2__terms-status { min-height: 1.2em; margin-top: -.28rem; color: #77736a; font-size: .72em; line-height: 1.35; }
    .dy-reader-v2__terms-status[data-state="error"] { color: #c97869; }
    .dy-reader-v2 dao-term {
      --dao-term-font: inherit;
      --dao-term-decoration-color: rgba(216,193,136,.5);
      --dao-term-hover-decoration-color: rgba(234,217,188,.9);
      --dao-term-hover-bg: rgba(216,193,136,.08);
      --dao-term-character-decoration: rgba(201,120,105,.58);
      --dao-term-character-decoration-hover: rgba(224,147,130,.9);
    }
    dao-term-popover {
      --dao-term-font: 'DaoYuan Serif','Noto Serif SC','Songti SC',serif;
      --dao-popover-bg: rgba(15,17,21,.985); --dao-popover-bg-solid: #0f1115;
      --dao-popover-border: rgba(216,193,136,.3); --dao-popover-border-soft: rgba(216,193,136,.16);
      --dao-popover-text: #e3dfcf; --dao-popover-muted: #918b79;
      --dao-popover-gold: #d8c188; --dao-popover-gold-hover: #f0dda9;
      --dao-popover-card-shadow: 0 1rem 2.6rem rgba(0,0,0,.55), inset 0 0 2rem rgba(216,193,136,.025);
      --dao-popover-button-bg: rgba(216,193,136,.045); --dao-popover-button-bg-hover: rgba(216,193,136,.1);
      --dao-popover-focus-ring: rgba(216,193,136,.72);
    }
    dao-modal-frame {
      --dao-term-font: 'DaoYuan Serif','Noto Serif SC','Songti SC',serif;
      --dao-frame-bg: #101319; --dao-frame-border: rgba(216,193,136,.32);
      --dao-frame-text: #e3dfcf; --dao-frame-muted: #918b79;
      --dao-frame-gold: #d8c188; --dao-frame-gold-dim: #806f45; --dao-frame-gold-hover: #f0dda9;
      --dao-frame-card-shadow: 0 1.25rem 3.5rem rgba(0,0,0,.62), inset 0 0 3rem rgba(216,193,136,.025);
      --dao-frame-button-bg: rgba(216,193,136,.05); --dao-frame-button-bg-hover: rgba(216,193,136,.11);
      --dao-frame-focus-ring: rgba(216,193,136,.72);
    }
    .dy-reader-v2__chronicle {
      display: flex;
      align-items: baseline;
      justify-content: center;
      gap: .5em;
      width: calc(100% - 8rem);
      min-width: 0;
      margin: 0;
      color: #8d8879;
      font-size: .88em;
      line-height: 1.018;
      letter-spacing: .065em;
      white-space: nowrap;
    }
    .dy-reader-v2__chronicle[hidden] { display: none; }
    .dy-reader-v2__chronicle > * { min-width: 0; line-height: inherit; }
    .dy-reader-v2__chronicle > * + *::before { content: '·'; margin-right: .5em; color: #665e48; }
    .dy-reader-v2__place { flex: 0 0 auto; color: #9c957f; }
    .dy-reader-v2__place::before { content: '◇'; margin-right: .5em; color: #c1aa70; }
    .dy-reader-v2__time { flex: 0 0 auto; color: #cdbb8e; font-size: 1.08em; letter-spacing: .09em; }
    .dy-reader-v2__date { flex: 0 0 auto; }
    .dy-reader-v2__mood { flex: 0 0 auto; font-style: italic; color: #777264; }
    .dy-reader-v2__source-time-card { display: none !important; }
    .dy-reader-v2__header::after {
      content: '';
      width: min(15rem, 66%);
      height: 1px;
      margin-top: .55rem;
      background: linear-gradient(90deg, transparent, rgba(216,193,136,.52), transparent);
    }
    .dy-reader-v2__kicker {
      color: var(--dy-gold-dim);
      font-size: .72em;
      line-height: 1.2;
      letter-spacing: .38em;
      text-indent: .38em;
    }
    .dy-reader-v2__title {
      margin: 0;
      color: var(--dy-gold);
      font-size: clamp(1.08rem, 1rem + .45vw, 1.34rem);
      font-weight: 600;
      line-height: 1.35;
      letter-spacing: .22em;
      text-indent: .22em;
      text-shadow: 0 1px 10px rgba(216,193,136,.09);
    }
    .dy-reader-v2__subtitle {
      color: #8e897a;
      font-size: .69em;
      line-height: 1.4;
      letter-spacing: .16em;
    }
    .dy-reader-v2__seal {
      position: absolute;
      right: clamp(.85rem, 3vw, 1.55rem);
      top: 1rem;
      display: grid;
      place-items: center;
      width: 1.8rem;
      height: 1.8rem;
      border: 1px solid rgba(191,93,78,.62);
      color: #c97869;
      font-size: .72rem;
      line-height: 1;
      transform: rotate(4deg);
      opacity: .78;
    }
    .dy-reader-v2__settings-button.dy-reader-v2__seal {
      display: grid; place-items: center; padding: 0;
      color: #c97869; background: rgba(18,17,17,.38);
      border: 1px solid rgba(191,93,78,.62); border-radius: 0;
      font: 500 .72rem/1 'DaoYuan Serif','Noto Serif SC',serif;
      cursor: pointer; opacity: .86;
    }
    .dy-reader-v2__settings-button.dy-reader-v2__seal:hover {
      color: #e09382; border-color: rgba(218,111,92,.86); background: rgba(105,43,36,.14);
    }
    .mes_text .dy-reader-v2 .dy-reader-v2__body {
      position: relative;
      padding: clamp(1.25rem, 3.6vw, 2.15rem) clamp(1.05rem, 5vw, 2.8rem) 1.35rem;
      font-size: var(--dy-reader-font-size, 18px);
      line-height: 1.76;
      letter-spacing: .035em;
      overflow-wrap: anywhere;
      word-break: normal;
      hanging-punctuation: first last;
    }
    .mes_text .dy-reader-v2 .dy-reader-v2__body > p {
      margin: 0 0 1.76em !important;
      font-family: inherit !important;
      font-size: inherit !important;
      line-height: inherit !important;
      letter-spacing: inherit !important;
      text-align: justify;
      text-justify: inter-ideograph;
      text-indent: 2em;
    }
    .mes_text .dy-reader-v2 .dy-reader-v2__body > p:last-child { margin-bottom: 0 !important; }
    #chat .mes_text .dy-reader-v2.dy-reader-v2--moonlit .dy-reader-v2__body > p {
      margin: 0 0 1.76em !important;
      font-family: inherit !important;
      font-size: inherit !important;
      line-height: inherit !important;
      letter-spacing: inherit !important;
    }
    #chat .mes_text .dy-reader-v2.dy-reader-v2--moonlit .dy-reader-v2__body > p:last-child {
      margin-bottom: 0 !important;
    }
    .mes_text .dy-reader-v2 .dy-reader-v2__body > p.dy-reader-v2__opening::first-letter {
      display: inline;
      float: none;
      margin: 0 .08em 0 0;
      vertical-align: baseline;
      color: var(--dy-gold);
      font-size: 1.8em;
      font-weight: 600;
      line-height: 1;
      text-shadow: 0 2px 12px rgba(216,193,136,.12);
    }
    .dy-reader-v2__body q {
      color: #ead9bc;
      text-decoration: underline;
      text-decoration-color: rgba(216,193,136,.18);
      text-underline-offset: .22em;
      text-decoration-thickness: 1px;
    }
    .dy-reader-v2__body q::before,
    .dy-reader-v2__body q::after { content: none; }
    .dy-reader-v2__body blockquote {
      margin: 1.15em .35em;
      padding: .7em 1em;
      color: var(--dy-text-soft);
      border-inline-start: 2px solid rgba(216,193,136,.42);
      background: rgba(216,193,136,.035);
    }
    .dy-reader-v2__body h1,
    .dy-reader-v2__body h2,
    .dy-reader-v2__body h3 {
      margin: 1.5em 0 .8em;
      color: var(--dy-gold);
      line-height: 1.4;
      letter-spacing: .12em;
      text-align: center;
    }
    .dy-reader-v2__body hr {
      width: min(13rem, 60%);
      height: 1px;
      margin: 1.5em auto;
      border: 0;
      background: linear-gradient(90deg, transparent, rgba(216,193,136,.42), transparent);
    }
    .dy-reader-v2__body pre,
    .dy-reader-v2__body code {
      white-space: pre-wrap;
      overflow-wrap: anywhere;
    }
    .mes_text .dy-reader-v2 .dy-reader-v2__footer {
      display: flex;
      align-items: center;
      gap: .8rem;
      padding: .85rem 1.35rem 1.05rem;
      color: #716d62;
      font-size: .68em;
      letter-spacing: .2em;
    }
    .dy-reader-v2__footer::before,
    .dy-reader-v2__footer::after {
      content: '';
      flex: 1;
      height: 1px;
      background: linear-gradient(90deg, transparent, rgba(216,193,136,.18));
    }
    .dy-reader-v2__footer::after { transform: scaleX(-1); }
    @media (max-width: 520px) {
      .dy-reader-v2 { margin-block: .45rem; border-left-width: 2px; }
      .mes_text .dy-reader-v2 .dy-reader-v2__header { padding: 1.05rem .85rem .85rem; }
      .dy-reader-v2__seal { right: .65rem; top: .7rem; width: 1.55rem; height: 1.55rem; }
      .dy-reader-v2__body { padding: 1.15rem .95rem 1.1rem; line-height: 1.72; letter-spacing: .02em; }
      .dy-reader-v2__chronicle { width: calc(100% - 5.2rem); justify-content: flex-start; font-size: .84em; overflow: hidden; }
      .dy-reader-v2__place { flex: 1 1 auto; }
      .dy-reader-v2__date, .dy-reader-v2__mood { display: none; }
      .dy-reader-v2__time { flex: 0 0 auto; }
      .dy-reader-v2__body > p { margin-bottom: .92em; }
      .dy-reader-v2__footer { padding-inline: .9rem; }
    }
    @media (max-width: 600px) {
      .dy-reader-v2__chronicle {
        flex-wrap: wrap;
        justify-content: center;
        row-gap: .38em;
        width: calc(100% - 4.5rem);
        overflow: visible;
        white-space: normal;
      }
      .dy-reader-v2__chronicle > * {
        flex: 0 0 100%;
        width: 100%;
        white-space: nowrap;
        text-align: center;
      }
      .dy-reader-v2__chronicle > .dy-reader-v2__place {
        max-width: 100%;
        white-space: normal;
        overflow-wrap: anywhere;
      }
      .dy-reader-v2__date,
      .dy-reader-v2__mood { display: block; }
    }
    .mes_text .dy-reader-v2 .dy-reader-v2__dialogue {
      display: grid;
      grid-template-columns: clamp(2.5rem, 4vw, 3.1rem) minmax(0, 1fr);
      grid-template-rows: auto auto;
      column-gap: .68rem;
      row-gap: .32rem;
      align-items: stretch;
      margin: 1.35em 0;
      padding: .56em;
      border: 1px solid rgba(216,193,136,.2);
      border-inline-start: 2px solid rgba(216,193,136,.52);
      border-radius: .4rem;
