    if (!terms || (event.key !== 'Enter' && event.key !== ' ')) return;
    event.preventDefault(); event.stopImmediatePropagation(); terms.click();
  }

  function handleSettingsChange(event) {
    const select = event.target?.closest?.('.dy-reader-v2__settings select');
    if (!select) return;
    event.stopImmediatePropagation();
    const article = select.closest(PAPER_SELECTOR);
    if (!article) return;
    article.dataset.font = select.value;
    try { storageFor(article.ownerDocument)?.setItem('daoyuan-reader-font', select.value); } catch (_) {}
  }

  function handleSettingsInput(event) {
    const input = event.target?.closest?.('.dy-reader-v2__settings input[type="range"]');
    if (!input) return;
    event.stopImmediatePropagation();
    const article = input.closest(PAPER_SELECTOR);
    if (!article) return;
    const value = input.value + 'px';
    input.style.setProperty('--dy-size-progress', ((Number(input.value) - 15) / 9 * 100) + '%');
    article.style.setProperty('--dy-reader-font-size', value);
    const output = article.querySelector('.dy-reader-v2__size-value');
    if (output) { output.value = value; output.textContent = value; }
    try { storageFor(article.ownerDocument)?.setItem('daoyuan-reader-size', input.value); } catch (_) {}
  }

  function timeMetadata(raw) {
    const match = String(raw || '').match(/<time_format>\s*time\s*[:：]\s*([\s\S]*?)☆([^\(\n\r]+)(?:\(([^\n\r]*?)\))?\s*scene\s*[:：]\s*([\s\S]*?)\s*<\/time_format>/i);
    if (!match) return null;
    const value = index => String(match[index] || '').replace(/<[^>]+>/g, '').trim();
    const metadata = { date: value(1), time: value(2), mood: value(3), place: value(4) };
    return metadata.date && metadata.time && metadata.place ? metadata : null;
  }

  function hideOriginalTimeCard(article, metadata) {
    const messageText = article.closest('.mes_text');
    if (!messageText) return;
    messageText.querySelectorAll(':scope > div, :scope > p').forEach(candidate => {
      if (candidate === article || candidate.contains(article)) return;
      const text = comparableSpeech(candidate.textContent);
      const fields = [metadata.date, metadata.time, metadata.place].filter(value => text.includes(comparableSpeech(value)));
      if (fields.length >= 2) candidate.classList.add('dy-reader-v2__source-time-card');
    });
  }

  function syncChronicle(article) {
    const metadata = timeMetadata(rawMessageForArticle(article));
    const chronicle = article.querySelector('.dy-reader-v2__chronicle');
    const subtitle = article.querySelector('.dy-reader-v2__subtitle');
    if (!chronicle) return;
    if (!metadata) {
      chronicle.hidden = true;
      chronicle.querySelectorAll('.dy-reader-v2__place, .dy-reader-v2__time, .dy-reader-v2__date, .dy-reader-v2__mood').forEach(node => { node.textContent = ''; });
      if (subtitle) subtitle.hidden = false;
      article.closest('.mes_text')?.querySelectorAll('.dy-reader-v2__source-time-card').forEach(node => node.classList.remove('dy-reader-v2__source-time-card'));
      return;
    }
    chronicle.querySelector('.dy-reader-v2__place').textContent = metadata.place;
    chronicle.querySelector('.dy-reader-v2__time').textContent = metadata.time;
    chronicle.querySelector('.dy-reader-v2__date').textContent = metadata.date;
    chronicle.querySelector('.dy-reader-v2__mood').textContent = metadata.mood || '';
    chronicle.hidden = false;
    if (subtitle) subtitle.hidden = true;
    hideOriginalTimeCard(article, metadata);
  }

  function mergeSettingsControl(article) {
    const header = article.querySelector('.dy-reader-v2__header');
    const button = header?.querySelector('.dy-reader-v2__settings-button');
    if (!header || !button) return;
    header.querySelectorAll('.dy-reader-v2__seal').forEach(node => { if (node !== button) node.remove(); });
    button.classList.add('dy-reader-v2__seal');
    button.textContent = '阅';
    button.title = '阅读设置';
    button.setAttribute('aria-label', '阅读设置');
  }

  function promoteVisibleSpeakerDialogues(article) {
    const body = article.querySelector('.dy-reader-v2__body');
    if (!body) return;
    const pattern = /^\s*[{｛]\s*([^{}｛｝\n]{1,40}?)\s*[}｝]\s*([“「『][\s\S]*[”」』])\s*$/;
    [...body.querySelectorAll(':scope > p')].forEach(paragraph => {
      const match = paragraph.textContent.match(pattern);
      if (!match) return;
      const speaker = normalizedSpeaker(match[1]);
      const spoken = String(match[2] || '').trim();
      if (!speaker || !spoken) return;
      const dialogue = body.ownerDocument.createElement('dialogue');
      dialogue.setAttribute('speaker', speaker);
      dialogue.textContent = spoken;
      paragraph.replaceWith(dialogue);
    });
  }

  function termPreference(doc) {
    try { return storageFor(doc)?.getItem(TERM_WIDGET_PREF) === 'true'; } catch (_) { return false; }
  }

  function setTermPreference(doc, enabled) {
    try { storageFor(doc)?.setItem(TERM_WIDGET_PREF, String(enabled)); } catch (_) {}
  }

  function termApi(doc) { return doc.defaultView?.DaoYuanTermWidget; }

  function protectReaderChrome(article) {
    article.querySelector('.dy-reader-v2__header')?.setAttribute('data-daoyuan-term-ignore', '');
    article.querySelector('.dy-reader-v2__footer')?.setAttribute('data-daoyuan-term-ignore', '');
    article.querySelectorAll('.dy-reader-v2__speaker').forEach(node => node.setAttribute('data-daoyuan-term-ignore', ''));
  }

  function setTermScanEnabled(doc, enabled) {
    doc.querySelectorAll(PAPER_SELECTOR).forEach(article => {
      protectReaderChrome(article);
      const body = article.querySelector('.dy-reader-v2__body');
      if (body) body.toggleAttribute('data-daoyuan-term-ignore', !enabled);
    });
  }

  function upgradeSettingsPanel(article) {
    const settings = article.querySelector('.dy-reader-v2__settings');
    if (!settings) return;
    const oldTerms = settings.querySelector('.dy-reader-v2__terms-toggle');
    if (oldTerms && (oldTerms.tagName !== 'DIV' || !oldTerms.querySelector('.dy-reader-v2__terms-track'))) {
      const toggle = article.ownerDocument.createElement('div');
      toggle.className = 'dy-reader-v2__terms-toggle'; toggle.tabIndex = 0;
      toggle.setAttribute('role', 'switch'); toggle.setAttribute('aria-label', '启用道渊术语注解');
      toggle.setAttribute('aria-checked', String(termPreference(article.ownerDocument))); toggle.setAttribute('aria-disabled', 'false');
      const track = article.ownerDocument.createElement('span'); track.className = 'dy-reader-v2__terms-track'; track.setAttribute('aria-hidden', 'true');
      const text = article.ownerDocument.createElement('span'); text.className = 'dy-reader-v2__terms-text'; text.textContent = '术语注解（联网）';
      toggle.append(track, text); oldTerms.replaceWith(toggle);
    }
    const range = settings.querySelector('input[type="range"]');
    if (range && !range.closest('.dy-reader-v2__size-scale')) {
      const scale = article.ownerDocument.createElement('span'); scale.className = 'dy-reader-v2__size-scale';
      const small = article.ownerDocument.createElement('span'); small.className = 'dy-reader-v2__size-glyph'; small.textContent = 'A'; small.setAttribute('aria-hidden', 'true');
      const large = article.ownerDocument.createElement('span'); large.className = 'dy-reader-v2__size-glyph dy-reader-v2__size-glyph--large'; large.textContent = 'A'; large.setAttribute('aria-hidden', 'true');
      range.replaceWith(scale); scale.append(small, range, large);
    }
    if (range) range.style.setProperty('--dy-size-progress', ((Number(range.value) - 15) / 9 * 100) + '%');
  }

  function updateTermControls(doc, state, message = '') {
    const enabled = termPreference(doc);
    doc.querySelectorAll('.dy-reader-v2__terms-toggle').forEach(input => {
      const checked = String(enabled); if (input.getAttribute('aria-checked') !== checked) input.setAttribute('aria-checked', checked);
      input.setAttribute('aria-disabled', String(state === 'loading'));
    });
    doc.querySelectorAll('.dy-reader-v2__terms-status').forEach(status => {
      status.dataset.state = state; if (status.textContent !== message) status.textContent = message;
    });
  }

  async function ensureTermWidget(doc) {
    if (termWidgetLoading) return termWidgetLoading;
    setTermScanEnabled(doc, true);
    updateTermControls(doc, 'loading', '正在载入术语库…');
    termWidgetLoading = (async () => {
      let api = termApi(doc);
      if (!api?.autoInstall) {
        const loaderDoc = doc;
        let script = loaderDoc.getElementById(TERM_WIDGET_SCRIPT_ID);
        if (!script) {
          termWidgetManaged = true;
          script = loaderDoc.createElement('script'); script.id = TERM_WIDGET_SCRIPT_ID; script.type = 'module'; script.src = TERM_WIDGET_URL;
          (loaderDoc.head || loaderDoc.documentElement).appendChild(script);
        }
        await new Promise((resolve, reject) => {
          if (termApi(doc)?.autoInstall) { resolve(); return; }
          const timer = setTimeout(() => reject(new Error('术语插件载入超时')), 25000);
          script.addEventListener('load', () => { clearTimeout(timer); resolve(); }, { once: true });
          script.addEventListener('error', () => { clearTimeout(timer); reject(new Error('术语插件载入失败')); }, { once: true });
        });
        api = termApi(doc);
      }
      if (!api?.autoInstall) throw new Error('术语插件接口不可用');
      termWidgetInstance = await api.autoInstall();
      updateTermControls(doc, 'ready', '已启用 · 点击正文术语查看 iWiki');
    })().catch(error => {
      setTermPreference(doc, false); setTermScanEnabled(doc, false);
      updateTermControls(doc, 'error', error?.message || '术语插件载入失败');
    }).finally(() => { termWidgetLoading = null; });
    return termWidgetLoading;
  }

  function disableTermWidget(doc) {
    setTermScanEnabled(doc, false);
    try { termWidgetInstance?.refresh?.(); } catch (_) {}
    if (termWidgetManaged) { try { termWidgetInstance?.uninstall?.(); } catch (_) {} termWidgetInstance = null; }
    updateTermControls(doc, 'idle', '已关闭');
  }

  function syncTermFeature(doc) {
    const enabled = termPreference(doc);
    setTermScanEnabled(doc, enabled);
    updateTermControls(doc, enabled ? 'loading' : 'idle', enabled ? '正在载入术语库…' : '默认关闭');
    if (enabled) ensureTermWidget(doc);
  }

  function renderAll() {
    const doc = hostDocument();
    ensureStyle(doc);
    ensurePortraitCatalog(doc);
    const moonlit = hasMoonlitEchoes(doc);
    doc.querySelectorAll('.mes_text content, content').forEach(buildReader);
    doc.querySelectorAll(PAPER_SELECTOR).forEach(article => {
      repairEmptyReader(article);
      mergeSettingsControl(article);
      trimBoundaryBreaks(article);
      syncThemeCompatibility(article, moonlit);
      syncChronicle(article);
      promoteVisibleSpeakerDialogues(article);
      promoteCommentDialogues(article);
      renderTaggedDialogues(article);
      refreshDialoguePortraits(article);
      upgradeSettingsPanel(article);
      protectReaderChrome(article);
    });
    const termsEnabled = termPreference(doc);
    setTermScanEnabled(doc, termsEnabled);
    updateTermControls(doc, termsEnabled ? (termWidgetInstance ? 'ready' : 'loading') : 'idle', termsEnabled ? (termWidgetInstance ? '已启用 · 点击正文术语查看 iWiki' : '正在载入术语库…') : '默认关闭');
  }

  window[INSTANCE_KEY]?.destroy?.();
  const doc = hostDocument();
  let scheduled = false;
  const schedule = () => {
    if (scheduled) return;
    scheduled = true;
    requestAnimationFrame(() => { scheduled = false; renderAll(); });
  };
  const observer = new MutationObserver(schedule);
  observer.observe(doc.body || doc.documentElement, { childList: true, subtree: true });
  doc.addEventListener('click', handleSettingsClick, true);
  doc.addEventListener('keydown', handleSettingsKeydown, true);
  doc.addEventListener('change', handleSettingsChange, true);
  doc.addEventListener('input', handleSettingsInput, true);
  window[INSTANCE_KEY] = { destroy() {
    observer.disconnect();
    doc.removeEventListener('click', handleSettingsClick, true);
    doc.removeEventListener('keydown', handleSettingsKeydown, true);
    doc.removeEventListener('change', handleSettingsChange, true);
    doc.removeEventListener('input', handleSettingsInput, true);
    doc.querySelectorAll('.dy-reader-v2__source-time-card').forEach(node => node.classList.remove('dy-reader-v2__source-time-card'));
    if (termWidgetManaged) { try { termWidgetInstance?.uninstall?.(); } catch (_) {} termWidgetInstance = null; }
    delete window[INSTANCE_KEY];
  } };
  renderAll();
  syncTermFeature(doc);
})();
